ChatSkill: FC<ChatSkillProps> = ({
  name,
  path,
  description,
  isUnsupported = false,
  labelClassName = 'dial-body-paragraph-text',
  unsupportedLabelClassName = 'text-error',
  unsupportedClassName = 'bg-error',
  onViewDetails,
  labels = {},
}) => {
  const {
    viewDetailsLabel = 'View details',
    unsupportedTooltipLabel = 'Selected model does not support skills. Remove the skill or select different model to proceed.',
  } = labels;

  /*
   * The tooltip is uncontrolled (the kit opens it on hover/focus) and exposes
   * no imperative close, so a "View details" click remounts it — the fresh
   * instance's open state starts closed. This mirrors the favorites rows,
   * whose tooltip unmounts with the Add menu on the same click; reopening
   * takes a fresh hover or focus, not the pointer already resting on the chip.
   */
  const [tooltipGeneration, setTooltipGeneration] = useState(0);

  const handleViewDetails = () => {
    setTooltipGeneration((generation) => generation + 1);
    onViewDetails(path);
  };

  return (
    <InteractiveTooltip
      key={tooltipGeneration}
      asChild
      placement={TooltipPlacement.Top}
      contentClassName="max-w-[550px]"
      content={
        isUnsupported ? (
          <SkillInfoTooltipContent
            unsupportedMessage={unsupportedTooltipLabel}
          />
        ) : (
          <SkillInfoTooltipContent
            description={description}
            viewDetailsLabel={viewDetailsLabel}
            onViewDetails={handleViewDetails}
          />
        )
      }
    >
      {/*
       * The span is the tooltip's trigger (`asChild`), so the tooltip stays
       * open while the pointer moves between it and the button. The button
       * body is presentation only — activating it does nothing beyond opening
       * the tooltip; removal is the host input's Backspace-at-start gesture.
       */}
      <span className="inline-flex items-center">
        {/*
         * `h-auto px-2 py-0` overrides the kit button's `h-[40px] px-4` so
         * the chip is exactly its label line (26px with the default
         * `dial-body-paragraph-text` label) plus 8px of horizontal padding —
         * no vertical padding, so the total height stays at the label line's
         * height and the chip's text aligns with the input's first text line.
         * In the error state the color classes join the layout/typography
         * classes so the whole chip reads as the error: error-tinted
         * background, error-colored `/{name}` label.
         */}
        <GhostButton
          label={`/${name}`}
          textClassName={
            isUnsupported
              ? mergeClasses(labelClassName, unsupportedLabelClassName)
              : labelClassName
          }
          className={mergeClasses(
            'h-auto px-2 py-0',
            isUnsupported && unsupportedClassName,
            SKILLS_CLASS.chip,
          )}
        />
      </span>
    </InteractiveTooltip>
  );
}

FavoriteSkillsPanel: FC<FavoriteSkillsPanelProps> = ({
  favorites,
  onSelect,
  onToggleFavorite,
  onBrowse,
  onViewDetails,
  searchQuery,
  labels = {},
  colors,
  nameClassName = 'dial-small-text',
  headerClassName = 'dial-tiny-lead-semi-text',
  emptyHintClassName = 'dial-small-text',
}) => {
  const {
    myCollectionLabel = 'My Collection',
    emptyHintLabel = 'Star a skill to pin it here',
    browseLabel = 'Browse',
    removeFromFavoritesLabel = 'Remove from favorites',
    viewDetailsLabel = 'View details',
    noMatchingSkillsLabel = 'No matching skills',
  } = labels;

  const cssVars = buildCssVars({
    '--fs-row-hover-bg': colors?.rowHoverBackground,
    '--fs-header-text': colors?.headerText,
    '--fs-empty-hint-text': colors?.emptyHintText,
    '--fs-star-color': colors?.starColor,
    '--fs-footer-border': colors?.footerBorder,
  });

  const [leavingIds, setLeavingIds] = useState<Set<string>>(new Set());
  const leaveTimeoutsRef = useRef(
    new Map<string, ReturnType<typeof setTimeout>>(),
  );

  useEffect(() => {
    const timeouts = leaveTimeoutsRef.current;
    return () => {
      timeouts.forEach((timeout) => clearTimeout(timeout));
      timeouts.clear();
    };
  }, []);

  const isSearchMode = searchQuery != null;
  const normalizedQuery = searchQuery?.toLowerCase() ?? '';
  const visibleFavorites = isSearchMode
    ? favorites.filter((item) =>
        item.name.toLowerCase().includes(normalizedQuery),
      )
    : favorites;

  /*
   * Animates the scrollable list's own height as rows leave instead of
   * letting it snap instantly, since CSS can't transition height: auto.
   */
  const listContentRef = useRef<HTMLDivElement>(null);
  const [listHeight, setListHeight] = useState<number>();

  useLayoutEffect(() => {
    if (listContentRef.current) {
      setListHeight(
        Math.min(listContentRef.current.scrollHeight, LIST_MAX_HEIGHT_PX),
      );
    }
  }, [favorites, searchQuery]);

  const handleKeyDown = (
    e: KeyboardEvent<HTMLDivElement>,
    item: FavoriteSkillItem,
  ) => {
    if (e.target !== e.currentTarget) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSelect(item);
    }
  };

  /*
   * Plays the row's fade-out animation before actually committing the
   * favorite change, since applying it immediately would make the row
   * (and its own animation) disappear instantly.
   */
  const handleToggleFavorite = (id: string) => {
    setLeavingIds((prev) => new Set(prev).add(id));
    const timeout = setTimeout(() => {
      onToggleFavorite(id);
      setLeavingIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
      leaveTimeoutsRef.current.delete(id);
    }, ROW_LEAVE_ANIMATION_MS);
    leaveTimeoutsRef.current.set(id, timeout);
  };

  const renderRow = (item: FavoriteSkillItem) => {
    const row = (
      <div
        role="button"
        tabIndex={0}
        className={mergeClasses(
          'flex cursor-pointer items-center gap-2 rounded-lg border border-transparent px-2 py-1.5 transition-colors',
          styles.row,
        )}
        onClick={() => onSelect(item)}
        onKeyDown={(e) => handleKeyDown(e, item)}
      >
        <DeploymentIcon size={DIAL_ICON_SIZE.MD} initialsName={item.name} />
        {searchQuery != null ? (
          <Highlight
            text={item.name}
            query={searchQuery}
            maxLines={1}
            className={mergeClasses(nameClassName, 'min-w-0 flex-1 text-start')}
          />
        ) : (
          <span
            className={mergeClasses(
              nameClassName,
              'min-w-0 flex-1 truncate text-start',
            )}
          >
            {item.name}
          </span>
        )}
        <ToggleIconButton
          icon={
            <IconStarFilled
              size={DIAL_ICON_SIZE.SM}
              className={styles.star}
              aria-hidden
            />
          }
          aria-label={removeFromFavoritesLabel}
          /* Every row in this panel is a favorite, so the star is always on. */
          isSelected
          onClick={(e) => {
            e.stopPropagation();
            handleToggleFavorite(item.id);
          }}
        />
      </div>
    );

    return (
      <li
        key={item.id}
        className={
          leavingIds.has(item.id) ? styles.rowLeaving : styles.rowEnter
        }
      >
        {/*
         * The row stays the focus/click target (`asChild`); the tooltip is
         * uncontrolled — the kit opens it on hover or keyboard focus and keeps
         * it open while the pointer travels between the row and the panel —
         * and renders nothing on touch-only devices, where tapping the row
         * still selects the skill.
         */}
        <InteractiveTooltip
          asChild
          contentClassName="max-w-[550px]"
          content={
            <SkillInfoTooltipContent
              description={item.description}
              viewDetailsLabel={viewDetailsLabel}
              onViewDetails={() => onViewDetails(item)}
            />
          }
        >
          {row}
        </InteractiveTooltip>
      </li>
    );
  };

  /*
   * In search mode an empty list is the filter's result, not the empty
   * favorites state, so it gets its own hint — announced via aria-live since
   * the user is typing and the change has no other confirmation. An empty
   * query still shows every row, so it never reaches the no-matching branch.
   */
  const renderListBody = () => {
    if (visibleFavorites.length > 0) {
      return (
        <ul className="flex flex-col gap-1 px-1 pb-1">
          {visibleFavorites.map(renderRow)}
        </ul>
      );
    }

    if (isSearchMode && normalizedQuery !== '') {
      return (
        <p
          role="status"
          aria-live="polite"
          className={mergeClasses(
            emptyHintClassName,
            'px-4 py-4 text-start',
            styles.emptyHint,
          )}
        >
          {noMatchingSkillsLabel}
        </p>
      );
    }

    return (
      <p
        className={mergeClasses(
          emptyHintClassName,
          'px-4 py-4 text-start',
          styles.emptyHint,
        )}
      >
        {emptyHintLabel}
      </p>
    );
  };

  return (
    <div
      className={mergeClasses(
        'flex w-full flex-col desktop:w-[280px]',
        SKILLS_CLASS.favoritesPanel,
      )}
      style={cssVars}
    >
      <p
        className={mergeClasses(
          headerClassName,
          SECTION_HEADING_CLASS_NAME,
          styles.header,
        )}
      >
        {myCollectionLabel}
      </p>

      <div
        className={mergeClasses(
          'max-h-72 min-h-0 flex-1 overflow-y-auto',
          styles.listContent,
        )}
        style={{ maxHeight: listHeight }}
      >
        <div ref={listContentRef}>{renderListBody()}</div>
      </div>

      <div className={mergeClasses('border-t px-2 py-3', styles.footer)}>
        <GhostButton
          label={browseLabel}
          className="w-full justify-center"
          onClick={onBrowse}
        />
      </div>
    </div>
  );
}

SkillCatalogModal: FC<SkillCatalogModalProps> = ({
  isOpen,
  onClose,
  onSelect,
  title,
  renderContent,
}) => (
  <Popup
    open={isOpen}
    header={title}
    size={PopupSize.Lg}
    className="h-[min(90vh,860px)] !max-w-[min(95vw,1200px)] overflow-hidden"
    onClose={onClose}
  >
    <div className="h-[min(80vh,840px)] overflow-auto">
      <Suspense fallback={null}>
        {isOpen && renderContent(onSelect, onClose)}
      </Suspense>
    </div>
  </Popup>
)

SkillDetailsSidePanel: FC<SkillDetailsSidePanelProps> = (
  props,
) => <DetailsPanel {...props} />

SkillInfoTooltipContent: FC<SkillInfoTooltipContentProps> = ({
  description,
  unsupportedMessage,
  viewDetailsLabel = 'View details',
  onViewDetails,
}) => {
  /*
   * The unsupported state replaces the whole content: the message alone, no
   * description and no "View details" action — the skill cannot be sent as
   * selected, so there is nothing to open details for.
   */
  if (unsupportedMessage != null) {
    return <p className="text-start">{unsupportedMessage}</p>;
  }

  const hasDescription = description != null && description !== '';

  return (
    <div className="flex flex-col gap-3">
      {hasDescription && <p className="text-start">{description}</p>}
      {/*
       * The action is reachable regardless of the description's state —
       * present or absent. `self-start` keeps the button at the
       * content's start edge instead of stretching it across the panel;
       * `h-[24px]` caps the kit Standard button's 40px height to the design's
       * 24px (the Standard label class `dial-small-paragraph-semi-text`,
       * 14px/24px semibold, already matches the design spec — the kit's
       * `ElementSize.Small` is not used because it swaps the label to 12px
       * tiny typography).
       */}
      <Button
        variant={ButtonVariant.Primary}
        appearance={ButtonAppearance.Link}
        className="h-[24px] self-start"
        label={viewDetailsLabel}
        iconBefore={
          <IconEye
            size={DIAL_ICON_SIZE.SM}
            stroke={DIAL_KIT_ICON_STROKE}
            aria-hidden
          />
        }
        onClick={onViewDetails}
      />
    </div>
  );
}

useSkillSelectorOverlay = ({
  isEnabled,
  isSkillsSupported,
  skills,
  sharedWithMe,
  publicSkills,
  favoriteIds,
  onToggleFavorite,
  labels,
  historyChipLabelClassName,
  renderCatalogContent,
  detailsPanelComponent: DetailsPanelComponent,
}: UseSkillSelectorOverlayOptions): UseSkillSelectorOverlayResult => {
  const {
    addMenuLabel = 'Skills',
    backLabel = 'Back',
    catalogModalTitleLabel = 'Use skill',
    emptyQueryHintLabel = 'Type to filter',
    unsupportedTooltipLabel = 'Selected model does not support skills. Remove the skill or select different model to proceed.',
    panelLabels,
  } = labels ?? {};

  /*
   * The entry-point gate: both the feature flag and the deployment's own
   * support must hold. A selected skill, its removal gesture, and the
   * details panel survive an unsupported deployment — only the ways in are
   * hidden — so unlike `isEnabled` this never blanks the whole result.
   */
  const isSkillsEnabled = isEnabled && isSkillsSupported;

  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [detailsSkillId, setDetailsSkillId] = useState<string | null>(null);
  const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);

  const allSkills = useMemo<SkillListingEntry[]>(
    () => [...skills, ...(sharedWithMe ?? []), ...(publicSkills ?? [])],
    [skills, sharedWithMe, publicSkills],
  );

  /*
   * Url-keyed view of `allSkills` so per-url lookups (the selected skill,
   * history entries) are O(1) instead of a linear scan per entry per render.
   */
  const skillByUrl = useMemo<Map<string, SkillListingEntry>>(
    () => new Map(allSkills.map((skill) => [skill.url, skill])),
    [allSkills],
  );

  /*
   * Only skill items end up in the favorites list server-side, so matching on
   * `url` needs no nodeType filtering — folder URLs never appear in
   * `favoriteIds`.
   */
  const favoriteSkillItems = useMemo<FavoriteSkillItem[]>(
    () =>
      allSkills
        .filter((skill) => favoriteIds.has(skill.url))
        .map((skill) => buildFavoriteSkillItem(skill)),
    [allSkills, favoriteIds],
  );

  /*
   * Resolved from `allSkills` on every render rather than captured at
   * selection time, so a skill picked while the listing is still loading
   * (e.g. via a one-shot route state) renders once the listing settles.
   */
  const selectedSkill = useMemo(
    () =>
      selectedSkillId == null
        ? null
        : (skillByUrl.get(selectedSkillId) ?? null),
    [skillByUrl, selectedSkillId],
  );

  /*
   * A skill selected on a deployment that does not support skills: the chip
   * renders in its error state and hosts fold this into send-disabled.
   */
  const isSkillUnsupported = selectedSkill != null && !isSkillsSupported;

  const selectSkill = useCallback((skillId: string) => {
    setSelectedSkillId(skillId);
  }, []);

  const removeSelectedSkill = useCallback(() => {
    setSelectedSkillId(null);
  }, []);

  /*
   * The selection id is the skill's resource URL, so it is exposed as the
   * send-time path directly — even while the listing is still loading and
   * `selectedSkill` has not resolved yet (the id came from a selection entry
   * point, which always receives resource URLs).
   */
  const selectedSkillPath = selectedSkillId;

  /*
   * The send-time `custom_content.skills` payload: a single `{ url }` entry
   * while a skill is selected, `undefined` otherwise so the field is omitted
   * from the message entirely. Memoized on the selection id so hosts can hold
   * it in `useCallback`/`memo` deps without the identity churning on every
   * render (e.g. every streaming token re-rendering the conversation view).
   */
  const selectedSkills = useMemo<RequestSkill[] | undefined>(
    () => (selectedSkillId == null ? undefined : [{ url: selectedSkillId }]),
    [selectedSkillId],
  );

  /*
   * The selected skill's inline form: the shared tooltip content, with the
   * listing-sourced description — or, while the deployment does not support
   * skills, the error state (error-colored label, message-only tooltip).
   * Memoized so the element's identity stays stable across unrelated
   * re-renders (streaming) and the input hosting it as `inlineStartSlot` is
   * not needlessly re-rendered. The element carries no remove control —
   * removal is the input's Backspace-at-start gesture via
   * `removeSelectedSkill` (wired to `onInlineStartRemove`). "View details"
   * opens the same side panel the rows' action opens.
   */
  const selectedSkillElement = useMemo<ReactNode>(
    () =>
      selectedSkill == null ? null : (
        <ChatSkill
          name={selectedSkill.name}
          path={selectedSkill.url}
          description={selectedSkill.description}
          isUnsupported={isSkillUnsupported}
          onViewDetails={setDetailsSkillId}
          labels={{
            viewDetailsLabel: panelLabels?.viewDetailsLabel,
            unsupportedTooltipLabel,
          }}
        />
      ),
    [selectedSkill, isSkillUnsupported, panelLabels, unsupportedTooltipLabel],
  );

  /*
   * History display: one `ChatSkill` per `custom_content.skills` entry,
   * sharing the rows' "View details" panel. The name and description come
   * from the listing pools matched on the entry's url; a url no pool carries
   * (e.g. a skill the viewer cannot read) falls back to its last non-empty
   * segment with no description. The label class is host-supplied because
   * the chip renders beside the bubble's first text line and its height
   * should match that line.
   */
  const renderHistorySkills = useCallback(
    (entries: RequestSkill[] | undefined): ReactNode => {
      if (entries == null || entries.length === 0) {
        return null;
      }

      return entries.map((entry) => {
        const skill = skillByUrl.get(entry.url);
        const name = skill?.name ?? getSkillFallbackName(entry.url);

        return (
          <ChatSkill
            key={entry.url}
            name={name}
            path={entry.url}
            labelClassName={historyChipLabelClassName}
            description={skill?.description}
            onViewDetails={setDetailsSkillId}
            labels={{ viewDetailsLabel: panelLabels?.viewDetailsLabel }}
          />
        );
      });
    },
    [skillByUrl, historyChipLabelClassName, panelLabels],
  );

  const renderOverlay = useCallback(
    (onClose: () => void): ReactNode => (
      <FavoriteSkillsPanel
        favorites={favoriteSkillItems}
        onSelect={(item) => {
          selectSkill(item.id);
          onClose();
        }}
        onToggleFavorite={onToggleFavorite}
        onBrowse={() => {
          onClose();
          setIsCatalogOpen(true);
        }}
        onViewDetails={(item) => {
          /* Closing the Add menu unmounts the overlay and its open tooltip. */
          onClose();
          setDetailsSkillId(item.id);
        }}
        labels={panelLabels}
      />
    ),
    [favoriteSkillItems, selectSkill, onToggleFavorite, panelLabels],
  );

  const skillMenuOverlay = useMemo<MenuOverlayConfig | undefined>(
    () =>
      isSkillsEnabled
        ? {
            key: 'skills',
            title: addMenuLabel,
            icon: (
              <IconBlocks
                size={BASE_ICON_SIZE}
                aria-hidden
                stroke={DIAL_KIT_ICON_STROKE}
              />
            ),
            renderOverlay,
            backLabel,
          }
        : undefined,
    [isSkillsEnabled, addMenuLabel, backLabel, renderOverlay],
  );

  /*
   * The slash-command menu: same favorites panel as the Add-menu overlay, but
   * in search mode over the typed query. Every action consumes the `/query`
   * text from the textarea first (`close({ consumeQuery: true })`), so it is
   * never sent — including "View details", which would otherwise leave a
   * stale query behind while the side panel opens.
   */
  const commandMenu = useMemo<CommandMenuConfig | undefined>(
    () =>
      isSkillsEnabled
        ? {
            triggerPrefix: '/',
            menuLabel: addMenuLabel,
            emptyQueryHint: emptyQueryHintLabel,
            renderMenu: ({ query, close }) => (
              <FavoriteSkillsPanel
                favorites={favoriteSkillItems}
                searchQuery={query}
                onSelect={(item) => {
                  close({ consumeQuery: true });
                  selectSkill(item.id);
                }}
                onToggleFavorite={onToggleFavorite}
                onBrowse={() => {
                  close({ consumeQuery: true });
                  setIsCatalogOpen(true);
                }}
                onViewDetails={(item) => {
                  close({ consumeQuery: true });
                  setDetailsSkillId(item.id);
                }}
                labels={panelLabels}
              />
            ),
          }
        : undefined,
    [
      isSkillsEnabled,
      addMenuLabel,
      emptyQueryHintLabel,
      favoriteSkillItems,
      selectSkill,
      onToggleFavorite,
      panelLabels,
    ],
  );

  const skillCatalogModal = (
    <SkillCatalogModal
      isOpen={isCatalogOpen}
      onClose={() => setIsCatalogOpen(false)}
      onSelect={(id) => {
        selectSkill(id);
        setIsCatalogOpen(false);
      }}
      title={catalogModalTitleLabel}
      renderContent={renderCatalogContent}
    />
  );

  /*
   * Information-only by design: the panel a "View details" action opens shows
   * the skill's details and nothing else — selecting a skill belongs to the
   * rows, the slash menu, and the browse modal, and favorite toggling to the
   * rows. The host's panel component renders `DetailsPanel` read-only.
   */
  const skillDetailsPanel = (
    <Suspense fallback={null}>
      <DetailsPanelComponent
        skillId={detailsSkillId}
        onClose={() => setDetailsSkillId(null)}
      />
    </Suspense>
  );

  if (!isEnabled) {
    return {
      skillMenuOverlay: undefined,
      commandMenu: undefined,
      skillCatalogModal: null,
      skillDetailsPanel: null,
      selectedSkillElement: null,
      selectedSkillPath: null,
      selectedSkills: undefined,
      isSkillUnsupported: false,
      selectSkill: () => undefined,
      removeSelectedSkill: () => undefined,
      renderHistorySkills: () => null,
    };
  }

  return {
    skillMenuOverlay,
    commandMenu,
    skillCatalogModal,
    skillDetailsPanel,
    selectedSkillElement,
    selectedSkillPath,
    selectedSkills,
    isSkillUnsupported,
    selectSkill,
    removeSelectedSkill,
    renderHistorySkills,
  };
}

buildFavoriteSkillItem = (
  skill: SkillListingEntry,
): FavoriteSkillItem => ({
  id: skill.url,
  name: skill.name,
  description: skill.description,
})

export interface ChatSkillLabels {
  /** Label for the tooltip's "View details" action. Defaults to `'View details'`. */
  viewDetailsLabel?: string;
  /**
   * Message shown alone in the tooltip while `isUnsupported` is set, stating
   * that the selected model does not support skills and that the user should
   * remove the skill or select a different model to proceed.
   */
  unsupportedTooltipLabel?: string;
}

export interface ChatSkillProps {
  /** Display name, rendered after the `/` prefix in the button's label. */
  name: string;
  /**
   * The skill's resource URL (`skills/{bucket}/{path}`), passed to every
   * callback so the host never has to re-derive it.
   */
  path: string;
  /** The skill's listing-sourced description, shown in the tooltip. Omitted when empty. */
  description?: string;
  /**
   * Whether the current model/application does not support skills. While
   * `true` the `/{name}` label carries `unsupportedLabelClassName`, the chip
   * carries `unsupportedClassName`, and the tooltip shows the
   * unsupported-model message alone — no description paragraph and no
   * "View details" button.
   */
  isUnsupported?: boolean;
  /** CSS class applied to the `/name` label. Defaults to `'dial-body-paragraph-text'`. */
  labelClassName?: string;
  /**
